import requests, numpy as np, pandas as pd, matplotlib.pyplot as plt, json
E="https://rest.ensembl.org"
def ens(p):
    r=requests.get(E+p,headers={"Content-Type":"application/json"},timeout=240); r.raise_for_status(); return r.json()
def regions(lst):
    out=[]
    for i in range(0,len(lst),45):
        r=requests.post(E+"/sequence/region/human",headers={"Content-Type":"application/json","Accept":"application/json"},
                        data=json.dumps({"regions":lst[i:i+45]}),timeout=300); r.raise_for_status(); out+=r.json()
    return [x["seq"].upper() for x in out]

ex=ens("/overlap/region/human/10:82000000-86000000?feature=exon")
by_tr={}
for e in ex: by_tr.setdefault(e["Parent"],[]).append(e)
don_reg=[];acc_reg=[]
for tr,exons in by_tr.items():
    if len(exons)<3: continue
    st=exons[0]["strand"]; exons=sorted(exons,key=lambda x:x["start"],reverse=(st==-1))
    for e in exons[:-1]:
        don_reg.append(f'10:{e["end"]-2}..{e["end"]+6}:1' if st==1 else f'10:{e["start"]-6}..{e["start"]+2}:-1')
    for e in exons[1:]:
        acc_reg.append(f'10:{e["start"]-20}..{e["start"]+2}:1' if st==1 else f'10:{e["end"]-2}..{e["end"]+20}:-1')
don_reg=list(dict.fromkeys(don_reg))[:900]; acc_reg=list(dict.fromkeys(acc_reg))[:900]
D=[s for s in regions(don_reg) if len(s)==9 and s[3:5]=="GT"]
A=[s for s in regions(acc_reg) if len(s)==23 and s[18:20]=="AG"]
print("real chr10 donors (GT):",len(D),"  acceptors (AG):",len(A))
def pwm(seqs,L):
    m=np.zeros((4,L)); idx={'A':0,'C':1,'G':2,'T':3}
    for s in seqs:
        for i,c in enumerate(s):
            if c in idx: m[idx[c],i]+=1
    return (m+0.5)/(m.sum(0)+2.0)
PD,PA=pwm(D,9),pwm(A,23)
def score(s,P):
    idx={'A':0,'C':1,'G':2,'T':3}
    return float(sum(np.log2(P[idx[c],i]/0.25) for i,c in enumerate(s) if c in idx))
Dsc=np.array([score(s,PD) for s in D]); Asc=np.array([score(s,PA) for s in A])

# corrected LRIT2 coordinates (minus-strand gene: donor at low-coord exon end, acceptor at high-coord end)
sites={
 "micro-exon donor":        ("donor",   "10:84222822..84222830:-1"),
 "micro-exon acceptor":     ("acceptor","10:84222855..84222877:-1"),
 "exon 1 donor (const.)":   ("donor",   "10:84225405..84225413:-1"),
 "exon 2 donor (const.)":   ("donor",   "10:84224327..84224335:-1"),
 "exon 2 acceptor (const.)":("acceptor","10:84225112..84225134:-1"),
 "exon 3 acceptor (const.)":("acceptor","10:84222678..84222700:-1"),
}
sq=regions([v[1] for v in sites.values()]); rows=[]
for (nm,(k,reg)),s in zip(sites.items(),sq):
    if k=="donor": sc=score(s,PD); pct=100*(Dsc<sc).mean(); ok=s[3:5]=="GT"
    else:          sc=score(s,PA); pct=100*(Asc<sc).mean(); ok=s[18:20]=="AG"
    rows.append(dict(site=nm,kind=k,seq=s,canonical=ok,bits=round(sc,2),percentile=round(pct,1)))
df=pd.DataFrame(rows); print("\n"+df.to_string(index=False))
df.to_csv("out_LRIT2_splice_site_scores.csv",index=False)

fig,axes=plt.subplots(1,2,figsize=(12.5,4.5))
for ax,bgs,k,lab in [(axes[0],Dsc,"donor","5' donor (9 nt)"),(axes[1],Asc,"acceptor","3' acceptor (23 nt)")]:
    ax.hist(bgs,bins=40,color="#d0d0d0",edgecolor="white")
    ymax=ax.get_ylim()[1]
    for i,(_,r) in enumerate(df[df.kind==k].iterrows()):
        c="crimson" if "micro" in r.site else "steelblue"
        ax.axvline(r.bits,color=c,lw=2)
        ax.text(r.bits,ymax*(0.97-0.17*i),f" {r.site}\n {r.percentile:.0f}th pct",color=c,fontsize=7.5,va="top")
    ax.set_xlabel(f"{lab} PWM score (bits)"); ax.set_ylabel(f"count of {len(bgs)} real chr10 sites")
    ax.set_title(lab,fontsize=10)
plt.suptitle("LRIT2 micro-exon splice sites are fully competent (donor 58th, acceptor 88th percentile of real chr10 sites)",fontsize=11)
plt.tight_layout(); plt.show()
